(function(){function D(t){this.mode=0;this.data=t;this.parsed=[];for(var i=0;i<t.length;i++){this.parsed.push([t.charCodeAt(i)])}this.getLength=function(){return this.parsed.length};this.write=function(bb){for(var i=0;i<this.parsed.length;i++){var d=this.parsed[i];for(var j=0;j<d.length;j++)bb.put(d[j],8)}}}
function BitBuf(){this.buffer=[];this.length=0;this.put=function(num,len){for(var i=0;i<len;i++)this.putBit((num>>(len-i-1)&1)===1)};this.putBit=function(bit){this.buffer.push(bit?1:0);this.length++};this.getLengthInBits=function(){return this.length}}
function QR(data){this.version=4;this.modules=null;this.size=this.version;this.dataList=[];this.dataCache=null;this.addData=function(d){this.dataList.push(new D(d));this.dataCache=null};this.isDark=function(r,c){return this.modules[r][c]};this.make=function(){var bb=new BitBuf();for(var i=0;i<this.dataList.length;i++){bb.put(0,4);bb.put(this.dataList[i].getLength(),8);this.dataList[i].write(bb);}while(bb.getLengthInBits()%8!==0)bb.putBit(false);var len=this.size*this.size;this.dataCache=new Array(len);for(var k=0;k<len;k++){var v=0;if(k*8<bb.buffer.length){for(var j=0;j<8 && k*8+j<bb.buffer.length;j++){v=(v<<1)|bb.buffer[k*8+j];}}this.dataCache[k]=v;}this.modules=new Array(this.size);for(var r=0;r<this.size;r++){this.modules[r]=new Array(this.size);for(var c=0;c<this.size;c++)this.modules[r][c]=false}pos(this,0,0);pos(this,this.size-7,0);pos(this,0,this.size-7);timing(this);for(var k2=0;k2<this.dataCache.length;k2++){var rr=k2%this.size,cc=Math.floor(k2/this.size);if(this.modules[rr]&&this.modules[rr][cc]===false)this.modules[rr][cc]=(this.dataCache[k2]&1)===1}};this.addData(data);this.make();}
function pos(q,r,c){for(var y=0;y<7;y++)for(var x=0;x<7;x++){var dark=(y===0||y===6||x===0||x===6||(y>=2&&y<=4&&x>=2&&x<=4));if(q.modules[r+y]&&q.modules[r+y][c+x]!==undefined)q.modules[r+y][c+x]=dark}}
function timing(q){for(var i=8;i<q.size-8;i++){if(q.modules[6]&&q.modules[6][i]===false)q.modules[6][i]=i%2===0;if(q.modules[i]&&q.modules[i][6]===false)q.modules[i][6]=i%2===0}}
function render(div,opt){opt=opt||{};var text=opt.text||'',w=opt.width||256,h=opt.height||256;div.innerHTML='';var c=document.createElement('canvas');c.width=w;c.height=h;var ctx=c.getContext('2d');var q=new QR(text);var count=q.size;var cw=w/count,ch=h/count;ctx.fillStyle='#fff';ctx.fillRect(0,0,w,h);for(var r=0;r<count;r++){for(var col=0;col<count;col++){ctx.fillStyle=q.isDark(r,col)?'#000':'#fff';var dw=Math.ceil((col+1)*cw)-Math.floor(col*cw);var dh=Math.ceil((r+1)*ch)-Math.floor(r*ch);ctx.fillRect(Math.round(col*cw),Math.round(r*ch),dw,dh);}}div.appendChild(c)}
window.QRCode={toCanvas:function(canvas,text,opt,cb){try{var wrap=document.createElement('div');render(wrap,{text:text,width:opt.width||256,height:opt.width||256});var inner=wrap.querySelector('canvas');canvas.width=inner.width;canvas.height=inner.height;canvas.getContext('2d').drawImage(inner,0,0);cb&&cb();}catch(e){cb&&cb(e);}}};})();
